// --------------------------------------------------------- spawn allowlists -
// Structural guards: each app is ONLY ever spawned with these joined argv
// strings. Config-writers / repo-writers / daemons are unreachable.
const ALLOW: Record<string, Set<string>> = {
  sem: new Set(["--version", "-V", "update"]),
  graft: new Set(["--version", "version", "upgrade"]),
  codegraph: new Set(["--version", "-V", "upgrade", "upgrade --check"]),
  headroom: new Set(["--version", "-v", "update", "update -y"]),
};

function runGuarded(app: string, args: string[]) {
  const joined = args.join(" ");
  const allowed = ALLOW[app];
  if (!allowed || !allowed.has(joined)) fail(`internal guard: ${app} "${joined}" is not on the allowlist`);
  return run(app, args);
}

// ============================================================ LAYER 1: machine
// Ported ensure logic (per-app update semantics preserved), but ZERO ~/ config
// writes: global dotfiles are out of scope by design.

function ensureQmd(): void {
  const local = (() => {
    const r = run("qmd", ["--version"]);
    if (r.code !== 0) return null;
    const m = r.stdout.match(/(\d+\.\d+\.\d+)/);
    return m ? m[1] : null;
  })();
  const pkg = "@tobilu/qmd";
  if (local === null) {
    log("qmd missing — installing globally via npm...");
    const r = run("npm", ["install", "-g", pkg]);
    if (r.code !== 0) fail(`npm install -g ${pkg} failed (exit ${r.code}):\n${r.stderr}\nHint: global npm dir may need sudo, or use an nvm-managed Node.`);
    const after = run("qmd", ["--version"]);
    if (after.code !== 0) fail("qmd still not on PATH after install");
    log(`installed qmd ${after.stdout.trim()}`);
    return;
  }
  const v = run("npm", ["view", pkg, "version"]);
  if (v.code !== 0 || !v.stdout.trim()) {
    warn(`npm registry unreachable — skipping qmd update check (local ${local})`);
    return;
  }
  const latest = v.stdout.trim();
  if (latest === local) {
    log(`qmd up to date (${local})`);
    return;
  }
  log(`qmd ${local} < latest ${latest} — updating...`);
  const r = run("npm", ["install", "-g", pkg]);
  if (r.code !== 0) fail(`npm install -g ${pkg} failed (exit ${r.code}):\n${r.stderr}`);
  log(`qmd update complete (latest ${latest})`);
}

async function semLatest(): Promise<string | null> {
  try {
    const r = await fetch("https://api.github.com/repos/Ataraxy-Labs/sem/releases/latest", { headers: { Accept: "application/vnd.github+json" } });
    if (!r.ok) return null;
    const j: unknown = await r.json();
    const tag = typeof j === "object" && j !== null && "tag_name" in j ? String((j as { tag_name: unknown }).tag_name) : "";
    const v = tag.replace(/^v/, "");
    return /^\d+\.\d+\.\d+$/.test(v) ? v : null;
  } catch {
    return null;
  }
}

async function ensureSem(): Promise<void> {
  const version = (): string | null => {
    const r = runGuarded("sem", ["--version"]);
    const m = `${r.stdout}\n${r.stderr}`.match(/^\s*sem\s+v?(\d+\.\d+\.\d+)/m);
    return r.code === 0 && m ? m[1] : null;
  };
  if (version() === null) {
    const probe = runGuarded("sem", ["--version"]);
    if (probe.code === 0) {
      // sem-cli prints `sem <version>`; GNU Parallel's shim prints something else.
      fail(
        "the `sem` on PATH is not sem-cli (GNU Parallel's colliding binary — Ataraxy-Labs/sem#77).\n" +
          "Fix: put sem-cli first on PATH (e.g. alias sem=\"$HOME/.local/bin/sem\"), then re-run.\n" +
          `Observed: ${(probe.stdout || probe.stderr).trim().split("\n")[0]}`,
      );
    }
    log("sem missing — installing globally via npm...");
    const r = run("npm", ["install", "-g", "@ataraxy-labs/sem"]);
    if (r.code !== 0) fail(`npm install -g @ataraxy-labs/sem failed (exit ${r.code}):\n${r.stderr}\nHint: global npm dir may need sudo, or use an nvm-managed Node.`);
    const v = version();
    if (v === null) fail("sem still not identifiable on PATH after install");
    log(`installed sem ${v}`);
    return;
  }
  const local = version() as string;
  const latest = await semLatest();
  if (latest === null) {
    warn(`GitHub releases unreachable — skipping sem update check (local ${local})`);
    return;
  }
  if (latest === local) {
    log(`sem up to date (${local})`);
    return;
  }
  log(`sem ${local} != latest ${latest} — running sem update...`);
  const u = runGuarded("sem", ["update"]);
  if (u.code !== 0) fail(`sem update failed (exit ${u.code}):\n${u.stderr || u.stdout}`);
  const after = version();
  if (after === null) fail("sem not identifiable after update");
  log(`sem update complete (sem ${after})`);
}

function ensureGraft(): void {
  const node = run("node", ["--version"]);
  if (node.code !== 0) fail("node not found on PATH (required, >=20) — install Node 20+ and re-run");
  const nm = node.stdout.trim().match(/^v(\d+)/);
  if (!nm) fail(`cannot parse node version from: ${node.stdout.trim() || node.stderr.trim()}`);
  if (Number(nm[1]) < 20) fail(`node v${nm[1]} too old — graft requires Node >=20`);
  const probe = runGuarded("graft", ["--version"]);
  if (probe.code !== 0) {
    log("graft missing — installing globally via npm...");
    const r = run("npm", ["install", "-g", "@nanonets/graft"]);
    if (r.code !== 0) fail(`npm install -g @nanonets/graft failed (exit ${r.code}):\n${r.stderr}`);
    const after = runGuarded("graft", ["--version"]);
    if (after.code !== 0) fail("graft still not on PATH after install");
    log(`installed graft ${after.stdout.trim()}`);
    return;
  }
  const v = runGuarded("graft", ["version"]);
  if (v.code !== 0) {
    warn(`graft version check failed — skipping update check (local ${probe.stdout.trim()})`);
    return;
  }
  const vers = (`${v.stdout}\n${v.stderr}`).match(/\b\d+\.\d+\.\d+\b/g) ?? [];
  const installed = vers[0] ?? null;
  const latest = vers[1] ?? vers[0] ?? null;
  if (!installed) {
    warn("cannot parse graft version output — skipping update check");
    return;
  }
  if (!latest || latest === installed) {
    log(`graft up to date (${installed})`);
    return;
  }
  log(`graft ${installed} < latest ${latest} — running graft upgrade...`);
  const u = runGuarded("graft", ["upgrade"]);
  if (u.code !== 0) fail(`graft upgrade failed (exit ${u.code}):\n${u.stderr || u.stdout}`);
  const verify = runGuarded("graft", ["--version"]);
  if (verify.code !== 0) fail("graft not identifiable after upgrade");
  log(`graft upgrade complete (${verify.stdout.trim()})`);
}

function ensureCodegraph(): void {
  const probe = runGuarded("codegraph", ["--version"]);
  if (probe.code !== 0) {
    log("codegraph missing — installing globally via npm...");
    const r = run("npm", ["install", "-g", "@colbymchenry/codegraph"]);
    if (r.code !== 0) fail(`npm install -g @colbymchenry/codegraph failed (exit ${r.code}):\n${r.stderr}\nHint: package engines declare node <25 (npm warns non-strict).`);
    const after = runGuarded("codegraph", ["--version"]);
    if (after.code !== 0) fail("codegraph still not on PATH after install");
    log(`installed codegraph ${after.stdout.trim()}`);
    return;
  }
  const c = runGuarded("codegraph", ["upgrade", "--check"]);
  const vers = (`${c.stdout}\n${c.stderr}`).match(/\bv\d+\.\d+\.\d+\b/g) ?? [];
  const nums = vers.map((x) => x.slice(1));
  const current = nums[0] ?? null;
  const latest = nums[1] ?? nums[0] ?? null;
  if (!current) {
    warn("cannot parse `codegraph upgrade --check` output (offline or format drift) — skipping update check");
    return;
  }
  if (!latest || latest === current) {
    log(`codegraph up to date (${current})`);
    return;
  }
  log(`codegraph ${current} < latest ${latest} — running codegraph upgrade...`);
  const u = runGuarded("codegraph", ["upgrade"]);
  if (u.code !== 0) fail(`codegraph upgrade failed (exit ${u.code}):\n${u.stderr || u.stdout}`);
  const verify = runGuarded("codegraph", ["--version"]);
  if (verify.code !== 0) fail("codegraph not identifiable after upgrade");
  log(`codegraph upgrade complete (${verify.stdout.trim()})`);
}

async function pypiLatest(pkg: string): Promise<string | null> {
  try {
    const r = await fetch(`https://pypi.org/pypi/${pkg}/json`);
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    const j: unknown = await r.json();
    const v = typeof j === "object" && j !== null && "info" in j ? (j as { info?: { version?: unknown } }).info?.version : undefined;
    return typeof v === "string" && /^\d+\.\d+\.\d+$/.test(v) ? v : null;
  } catch {
    return null;
  }
}

async function ensureHeadroom(): Promise<void> {
  const uv = run("uv", ["--version"]);
  if (uv.code !== 0) fail("uv not found on PATH — headroom installs via `uv tool install` — https://docs.astral.sh/uv/getting-started/installation/");
  const probe = runGuarded("headroom", ["--version"]);
  if (probe.code !== 0) {
    log("headroom missing — installing via uv tool...");
    const r = run("uv", ["tool", "install", "headroom-ai[all]"]);
    if (r.code !== 0) fail(`uv tool install "headroom-ai[all]" failed (exit ${r.code}):\n${r.stderr}`);
    const after = runGuarded("headroom", ["--version"]);
    if (after.code !== 0) fail("headroom still not on PATH after install");
    log(`installed headroom ${after.stdout.trim()}`);
    return;
  }
  const local = (`${probe.stdout}\n${probe.stderr}`).match(/(\d+\.\d+\.\d+)/)?.[1] ?? null;
  if (!local) {
    warn("cannot parse `headroom --version` output — skipping update check");
    return;
  }
  const latest = await pypiLatest("headroom-ai");
  if (latest === null) {
    warn("PyPI unreachable — skipping headroom update check (local untouched)");
    return;
  }
  if (latest === local) {
    log(`headroom up to date (${local})`);
    return;
  }
  log(`headroom ${local} < latest ${latest} — running headroom update...`);
  // -y: upstream prompts for confirmation; closed stdin would abort.
  const u = runGuarded("headroom", ["update", "-y"]);
  if (u.code !== 0) fail(`headroom update failed or refused (exit ${u.code}):\n${(u.stdout + u.stderr).trim()}`);
  const verify = runGuarded("headroom", ["--version"]);
  if (verify.code !== 0) fail("headroom not identifiable after update");
  const after = (`${verify.stdout}\n${verify.stderr}`).match(/(\d+\.\d+\.\d+)/)?.[1] ?? null;
  if (!after || after === local) {
    // Platform wheel ceiling (observed on Intel macOS): upstream prints success
    // while resolution keeps the installed version. Warn, continue.
    warn(`update did not advance headroom (local ${local}, latest ${latest}) — ${latest} unresolvable on this platform; ${local} is the newest installable here`);
    return;
  }
  log(`headroom update complete (${after})`);
}

// benzi: uv-channel ensure (headroom precedent). NEVER spawns benzi-mcp/
// benzi-login/benzi-headless — probe is `uv tool list benzi`; login = user action.
async function ensureBenzi(): Promise<void> {
  const uv = run("uv", ["--version"]);
  if (uv.code !== 0) fail("uv not found on PATH — benzi installs via `uv tool install benzi` — install uv from https://docs.astral.sh/uv/getting-started/installation/");
  const localVersion = (): string | null => {
    const r = run("uv", ["tool", "list"]);
    if (r.code !== 0) return null;
    return r.stdout.match(/^benzi v?(\d+\.\d+\.\d+)$/m)?.[1] ?? null;
  };
  const local = localVersion();
  if (local === null) {
    log("benzi missing — installing via uv tool...");
    const r = run("uv", ["tool", "install", "benzi"]);
    if (r.code !== 0) fail(`uv tool install benzi failed (exit ${r.code}):\n${r.stderr}\nHint: benzi wheels need Python >=3.11,<3.15 available to uv.`);
    const after = localVersion();
    if (after === null) fail("benzi still not installed after `uv tool install`");
    log(`installed benzi ${after}`);
    log("benzi-login not run (interactive email-code flow) — authenticate once before MCP use: benzi-login");
    return;
  }
  const latest = await pypiLatest("benzi");
  if (latest === null) {
    warn("PyPI unreachable — skipping benzi update check (local untouched)");
    return;
  }
  if (latest === local) {
    log(`benzi up to date (${local})`);
    return;
  }
  log(`benzi ${local} < latest ${latest} — upgrading...`);
  const u = run("uv", ["tool", "upgrade", "benzi"]);
  if (u.code !== 0) fail(`uv tool upgrade benzi failed (exit ${u.code}):\n${u.stderr}`);
  const after = localVersion();
  if (after === local) {
    warn(`upgrade did not advance benzi (local ${local}, latest ${latest}) — ${latest} unresolvable on this platform`);
    return;
  }
  log(`benzi upgrade complete (${after})`);
}

function gateJcodemunch(): void {
  const uvx = run("uvx", ["--version"]);
  if (uvx.code !== 0) fail("uvx not found on PATH — jcodemunch-mcp is spawned via uvx at MCP startup; install uv from https://docs.astral.sh/uv/");
  log(`uvx ${uvx.stdout.trim()} ok (jcodemunch-mcp resolves at spawn — gate only)`);
}

function gateContext7(): void {
  const node = run("node", ["--version"]);
  if (node.code !== 0) fail("node not found on PATH (required, >=18) — install Node 18+ and re-run");
  const nm = node.stdout.trim().match(/^v(\d+)/);
  if (nm && Number(nm[1]) < 18) fail(`node v${nm[1]} too old — context7 CLI fallback requires Node >=18`);
  const npx = run("npx", ["--version"]);
  if (npx.code !== 0) fail("npx not found on PATH — the skill's CLI fallback runs `npx ctx7@latest`");
  const v = run("npm", ["view", "ctx7", "version"]);
  if (v.code !== 0 || !v.stdout.trim()) {
    warn("npm registry unreachable — skipping ctx7 version report");
    return;
  }
  log(`latest ctx7: ${v.stdout.trim()} (gate only — npx resolves at call time)`);
}

function gateJev(): void {
  const node = run("node", ["--version"]);
  if (node.code !== 0) fail("node not found on PATH (required, >=22) — install Node 22+ and re-run");
  const nm = node.stdout.trim().match(/^v(\d+)/);
  if (nm && Number(nm[1]) < 22) fail(`node v${nm[1]} too old — jev-mcp requires Node >=22`);
  const npx = run("npx", ["--version"]);
  if (npx.code !== 0) fail("npx not found on PATH — it spawns @jkudish/jev-mcp at MCP startup");
  const v = run("npm", ["view", "@jkudish/jev-mcp", "version"]);
  if (v.code !== 0 || !v.stdout.trim()) {
    warn("npm registry unreachable — skipping jev-mcp version report");
    return;
  }
  log(`latest @jkudish/jev-mcp: ${v.stdout.trim()} (gate only — npx resolves at spawn)`);
}

// ---- LSP machine layer: hybrid bin ensure (npm auto; toolchain-gated report)
// npm-able bins -> 10 verified packages (vscode-langservers-extracted covers 2 bins).
// ============================================================ PROVISIONER
// User-scope everything (no admin/sudo): official installers + in-process PATH.
const PATH_SEP = isWin ? ";" : ":";
function addPathDir(dir: string): void {
  const cur = process.env.PATH ?? "";
  if (cur.split(PATH_SEP).includes(dir)) return;
  process.env.PATH = isWin ? `${dir};${cur}` : `${dir}:${cur}`;
}
async function download(url: string, dest: string): Promise<void> {
  let res: Response;
  try {
    res = await fetch(url);
  } catch (e) {
    fail(`download failed: ${url}\n${e instanceof Error ? e.message : e}`);
  }
  if (!res.ok) fail(`download failed (HTTP ${res.status}): ${url}`);
  writeFileSync(dest, Buffer.from(await res.arrayBuffer()));
}
function nodeMajor(): number | null {
  const r = run("node", ["--version"]);
  if (r.code !== 0) return null;
  const m = r.stdout.trim().match(/^v(\d+)/);
  return m ? Number(m[1]) : null;
}

async function ensureUv(): Promise<void> {
  if (run("uv", ["--version"]).code === 0) return;
  log("uv missing — provisioning (user-scope, official installer)...");
  const r = isWin
    ? run("powershell", ["-ExecutionPolicy", "ByPass", "-c", "irm https://astral.sh/uv/install.ps1 | iex"])
    : run("sh", ["-c", "curl -LsSf https://astral.sh/uv/install.sh | sh"]);
  if (r.code !== 0) fail(`uv provisioning failed (exit ${r.code}):\n${(r.stdout + r.stderr).trim()}`);
  addPathDir(join(homedir(), ".local", "bin"));
  const v = run("uv", ["--version"]);
  if (v.code !== 0) fail(`uv still not resolvable after provisioning — ensure ~/.local/bin is on PATH (new shell)`);
  log(`uv ${v.stdout.trim().replace(/^uv\s+/, "")} provisioned`);
}

async function ensureNode(): Promise<void> {
  const have = nodeMajor();
  if (have !== null && have >= 22) return;
  log(have === null
    ? "node missing — provisioning Node 22 LTS (user-scope portable)..."
    : `node v${have} < 22 — provisioning Node 22 LTS alongside (in-process PATH prefers it)...`);
  let list: Array<{ version: string }>;
  try {
    const res = await fetch("https://nodejs.org/dist/index.json");
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    list = (await res.json()) as Array<{ version: string }>;
  } catch (e) {
    fail(`Node provisioning failed: cannot read https://nodejs.org/dist/index.json\n${e instanceof Error ? e.message : e}`);
  }
  const v = (list.find((x) => /^v22\.\d+\.\d+$/.test(x.version)) ?? list.find((x) => /^v\d+\.\d+\.\d+$/.test(x.version)));
  if (!v) fail("Node provisioning failed: no stable release in dist index");
  const arch = process.arch === "arm64" ? "arm64" : "x64";
  const plat = isWin ? "win" : process.platform === "darwin" ? "darwin" : "linux";
  const file = `node-${v.version}-${plat}-${arch}.${isWin ? "zip" : "tar.gz"}`;
  const url = `https://nodejs.org/dist/${v.version}/${file}`;
  const dl = join(tmpdir(), file);
  log(`downloading ${url}...`);
  await download(url, dl);
  const root = join(homedir(), ".local");
  const extract = join(root, "node-extract");
  rmSync(extract, { recursive: true, force: true });
  mkdirSync(extract, { recursive: true });
  const tr = run("tar", ["-xf", dl, "-C", extract]);
  if (tr.code !== 0) fail(`Node archive extraction failed (exit ${tr.code}):\n${tr.stderr}`);
  const entry = readdirSync(extract).find((d) => d.startsWith("node-"));
  if (!entry) fail("Node archive extraction failed: no node-* directory found");
  const target = join(root, "node");
  rmSync(target, { recursive: true, force: true });
  renameSync(join(extract, entry), target);
  rmSync(extract, { recursive: true, force: true });
  rmSync(dl, { force: true });
  // posix tarball: binaries under node/bin · win zip: binaries at root
  addPathDir(isWin ? target : join(target, "bin"));
  const after = nodeMajor();
  if (after === null || after < 22) fail(`Node provisioning incomplete — node v${after ?? "absent"} on PATH`);
  log(`Node v${after} provisioned (${target})`);
}

async function ensureRust(): Promise<void> {
  if (run("rustup", ["--version"]).code === 0) return;
  addPathDir(join(homedir(), ".cargo", "bin"));
  if (run("rustup", ["--version"]).code === 0) return;
  log("rustup missing — provisioning Rust toolchain (user-scope, minimal profile)...");
  if (isWin) {
    const exe = join(tmpdir(), "rustup-init.exe");
    const d = run("curl.exe", ["-fsSL", "-o", exe, "https://win.rustup.rs/x86_64"]);
    if (d.code !== 0) fail(`rustup-init download failed (exit ${d.code}):\n${d.stderr}`);
    const r = run(exe, ["-y", "--default-toolchain", "stable", "--profile", "minimal"]);
    if (r.code !== 0) fail(`rustup-init failed (exit ${r.code}):\n${(r.stdout + r.stderr).trim()}`);
  } else {
    const r = run("sh", ["-c", "curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh -s -- -y --default-toolchain stable --profile minimal"]);
    if (r.code !== 0) fail(`rustup provisioning failed (exit ${r.code}):\n${(r.stdout + r.stderr).trim()}`);
  }
  addPathDir(join(homedir(), ".cargo", "bin"));
  if (run("rustup", ["--version"]).code !== 0) fail("rustup not resolvable after provisioning — ensure ~/.cargo/bin is on PATH (new shell)");
  log("Rust toolchain provisioned");
}

async function ensureDotnet(): Promise<void> {
  if (run("dotnet", ["--version"]).code === 0) {
    addPathDir(join(homedir(), ".dotnet", "tools"));
    return;
  }
  log("dotnet missing — provisioning .NET SDK (user-scope, LTS channel)...");
  if (isWin) {
    const ps1 = join(tmpdir(), "dotnet-install.ps1");
    const d = run("curl.exe", ["-fsSL", "-o", ps1, "https://dot.net/v1/dotnet-install.ps1"]);
    if (d.code !== 0) fail(`dotnet-install.ps1 download failed (exit ${d.code}):\n${d.stderr}`);
    const r = run("powershell", ["-ExecutionPolicy", "ByPass", "-File", ps1, "--channel", "LTS"]);
    if (r.code !== 0) fail(`.NET SDK provisioning failed (exit ${r.code}):\n${(r.stdout + r.stderr).trim()}`);
  } else {
    const sh = join(tmpdir(), "dotnet-install.sh");
    const d = run("curl", ["-fsSL", "-o", sh, "https://dot.net/v1/dotnet-install.sh"]);
    if (d.code !== 0) fail(`dotnet-install.sh download failed (exit ${d.code}):\n${d.stderr}`);
    const r = run("sh", [sh, "--channel", "LTS"]);
    if (r.code !== 0) fail(`.NET SDK provisioning failed (exit ${r.code}):\n${(r.stdout + r.stderr).trim()}`);
  }
  addPathDir(join(homedir(), ".dotnet"));
  addPathDir(join(homedir(), ".dotnet", "tools"));
  if (run("dotnet", ["--version"]).code !== 0) fail("dotnet not resolvable after provisioning — ensure ~/.dotnet is on PATH (new shell)");
  log(".NET SDK provisioned");
}

const LSP_NPM: Record<string, string> = {
  "typescript-language-server": "typescript-language-server",
  svelteserver: "svelte-language-server",
  "vscode-json-language-server": "vscode-langservers-extracted",
  "vscode-html-language-server": "vscode-langservers-extracted",
  "yaml-language-server": "yaml-language-server",
  "gh-actions-language-server": "gh-actions-language-server",
  "tailwindcss-language-server": "tailwindcss-language-server",
  "sql-language-server": "sql-language-server",
  biome: "@biomejs/biome",
  "docker-langserver": "dockerfile-language-server-nodejs",
  "bash-language-server": "bash-language-server",
  taplo: "@taplo/cli",
  buf: "@bufbuild/buf",
};
// Toolchain-channel bins: installed through their owning toolchain,
// provisioned user-scope first only if absent (brew is never spawned).
const LSP_CHANNELS: Record<string, "rust" | "dotnet" | "marksman"> = {
  "rust-analyzer": "rust",
  protols: "rust",
  marksman: "marksman",
  "csharp-ls": "dotnet",
};

function binOnPath(bin: string): boolean {
  const dirs = (process.env.PATH ?? "").split(isWin ? ";" : ":").filter(Boolean);
  const names = isWin ? [`${bin}.cmd`, `${bin}.exe`, bin] : [bin];
  for (const d of dirs) for (const n of names) if (existsSync(join(d, n))) return true;
  return false;
}

// marksman is NOT a dotnet/NuGet tool (verified: NuGet 404) — official channel
// is the GitHub release binary. User-scope: ~/.local/bin.
async function installMarksmanBinary(): Promise<number> {
  try {
    const res = await fetch("https://api.github.com/repos/artempyanykh/marksman/releases/latest", {
      headers: { "User-Agent": "agent-bootstrap" }
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const rel = (await res.json()) as { assets: Array<{ name: string; browser_download_url: string }> };
    const arch = process.arch === "arm64" ? "arm64" : "x64";
    const want = isWin
      ? "marksman.exe"
      : process.platform === "darwin"
        ? "marksman-macos"
        : `marksman-linux-${arch}`;
    const asset =
      rel.assets.find((a) => a.name === want) ??
      (isWin ? undefined : rel.assets.find((a) => a.name === `marksman-linux-musl-${arch}`));
    if (!asset) {
      warn(`marksman: no release asset for ${want} — install manually`);
      return 1;
    }
    const binDir = join(homedir(), ".local", "bin");
    mkdirSync(binDir, { recursive: true });
    const dest = join(binDir, isWin ? "marksman.exe" : "marksman");
    log(`marksman: downloading ${asset.name}...`);
    await download(asset.browser_download_url, dest);
    if (!isWin) chmodSync(dest, 0o755);
    addPathDir(binDir);
    return binOnPath("marksman") ? 0 : 1;
  } catch (e) {
    warn(`marksman channel failed: ${e instanceof Error ? e.message : e} — install manually`);
    return 1;
  }
}

async function ensureLspBins(): Promise<void> {
  const declared = (LSP_CONFIG.servers ?? []).map((s) => String(s.bin ?? "")).filter(Boolean);
  if (declared.length !== 17) fail(`LSP config must declare 17 server bins, found ${declared.length}`);
  const missingNpm: string[] = [];
  const missingChannel: string[] = [];
  for (const bin of declared) {
    if (binOnPath(bin)) continue;
    if (LSP_NPM[bin]) missingNpm.push(bin);
    else if (LSP_CHANNELS[bin]) missingChannel.push(bin);
    else warn(`LSP bin missing: ${bin} — no known channel; install it manually`);
  }
  // npm channel (13 bins) — dedupe by package (vscode-langservers-extracted serves 2 bins).
  const pkgs = Array.from(new Set(missingNpm.map((b) => LSP_NPM[b])));
  let installed = 0;
  for (const pkg of pkgs) {
    log(`installing LSP package ${pkg}...`);
    const r = run("npm", ["install", "-g", pkg]);
    if (r.code !== 0) warn(`npm install -g ${pkg} failed (exit ${r.code}): ${r.stderr.trim().split("\n").slice(-1)[0] ?? ""}`);
    else installed++;
  }
  // toolchain channels (4 bins) — provision owning toolchain only if absent.
  let channeled = 0;
  for (const bin of missingChannel) {
    const kind = LSP_CHANNELS[bin];
    log(`LSP ${bin}: installing via ${kind === "rust" ? "rustup/cargo" : kind === "marksman" ? "official binary release" : "dotnet"} channel...`);
    let code = 1;
    if (kind === "marksman") {
      code = await installMarksmanBinary();
    } else if (kind === "rust") {
      await ensureRust();
      const cmd = bin === "rust-analyzer" ? run("rustup", ["component", "add", "rust-analyzer"]) : run("cargo", ["install", bin]);
      code = cmd.code;
      if (code !== 0 && binOnPath(bin)) code = 0; // already installed elsewhere — end state wins
      else if (code !== 0) warn(`${bin} channel command failed (exit ${code}): ${(cmd.stdout + cmd.stderr).trim().split("\n").slice(-1)[0] ?? ""}`);
    } else {
      await ensureDotnet();
      const cmd = run("dotnet", ["tool", "install", "--global", bin]);
      code = cmd.code;
      if (code !== 0 && binOnPath(bin)) code = 0; // already installed elsewhere — end state wins
      else if (code !== 0) warn(`${bin} channel command failed (exit ${code}): ${(cmd.stdout + cmd.stderr).trim().split("\n").slice(-1)[0] ?? ""}`);
    }
    if (binOnPath(bin)) channeled++;
  }
  const stillMissing = declared.filter((b) => !binOnPath(b)).length;
  const present = 17 - stillMissing;
  log(`lsp bins: ${present}/17 present${installed ? `, ${installed} package(s) installed` : ""}${channeled ? `, ${channeled} via toolchain channel` : ""}${stillMissing ? `, ${stillMissing} missing (see warnings)` : ""}`);
}
// ---- LSP project layer: dual-write config (pi + agy), per-server-id template-wins
function writeLspConfig(): void {
  const targets = [".pi/lsp.json", ".antigravity/lsp.json"];
  for (const rel of targets) {
    const p = join(PROJECT_ROOT, rel);
    let existing: { version?: number; servers?: Array<Record<string, unknown>> } = {};
    if (existsSync(p)) {
      try {
        existing = JSON.parse(readFileSync(p, "utf8"));
      } catch (e) {
        fail(`unparseable JSON — refusing to overwrite: ${p}\n${e instanceof Error ? e.message : e}`);
      }
      if (typeof existing !== "object" || existing === null || Array.isArray(existing)) fail(`expected JSON object: ${p}`);
    }
    // Per-server-id, template-wins (mirrors pi-lsp's own merge semantics);
    // user-added extra server ids are preserved.
    const templateById = new Map((LSP_CONFIG.servers ?? []).map((s) => [String(s.id), s]));
    const existingServers = Array.isArray(existing.servers) ? existing.servers : [];
    const merged: Array<Record<string, unknown>> = [];
    const seen = new Set<string>();
    for (const item of existingServers) {
      const id = String((item as { id?: unknown }).id ?? "");
      const t = templateById.get(id);
      if (t) {
        merged.push(t);
        seen.add(id);
      } else {
        merged.push(item); // preserve user-added extras
      }
    }
    templateById.forEach((t, id) => {
      if (!seen.has(id)) merged.push(t);
    });
    const out = { version: LSP_CONFIG.version, servers: merged };
    const next = `${JSON.stringify(out, null, 2)}\n`;
    if (existsSync(p) && readFileSync(p, "utf8") === next) {
      log(`lsp config unchanged: ${rel}`);
      continue;
    }
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, next);
    log(`lsp config written: ${rel} (${merged.length} servers)`);
  }
}

// ============================================================ LAYER 2: project MCP
// ---- Pi packages: workspace-only pure file merge (no `pi` spawn) ------------
// Identity per pi's rules: npm name (version stripped), git repo without ref,
// else exact string. Project entry loads after project trust (pi's own gate).
function piPkgId(spec: string): string {
  if (spec.startsWith("npm:")) {
    const raw = spec.slice(4);
    const i = raw.lastIndexOf("@");
    return "npm:" + (i > 0 ? raw.slice(0, i) : raw);
  }
  if (spec.startsWith("git:")) return "git:" + spec.slice(4).split("@")[0];
  return spec;
}

function mergePiSettings(): void {
  const p = join(PROJECT_ROOT, ".pi", "settings.json");
  const manifest = JSON.parse(PI_PACKAGES_PAYLOAD) as { packages?: unknown[] };
  const want = Array.isArray(manifest.packages) ? manifest.packages : [];
  let cfg: Record<string, unknown> = {};
  const existed = existsSync(p);
  if (existed) {
    try {
      cfg = JSON.parse(readFileSync(p, "utf8"));
    } catch (e) {
      fail(`unparseable JSON — refusing to overwrite: ${p}\n${e instanceof Error ? e.message : e}`);
    }
    if (typeof cfg !== "object" || cfg === null || Array.isArray(cfg)) fail(`expected JSON object: ${p}`);
    if ("packages" in cfg && !Array.isArray(cfg.packages)) fail(`expected "packages" array in ${p}`);
  }
  const existing = existed && Array.isArray(cfg.packages) ? (cfg.packages as unknown[]) : [];
  const seen = new Set(existing.map(piPkgId));
  const added: unknown[] = [];
  for (const pkg of want) {
    const id = piPkgId(typeof pkg === "string" ? pkg : String((pkg as { source?: unknown }).source ?? ""));
    if (!seen.has(id)) {
      seen.add(id);
      added.push(pkg);
    }
  }
  if (!existed || added.length > 0) {
    cfg.packages = [...existing, ...added];
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, `${JSON.stringify(cfg, null, 2)}\n`);
    log(existed
      ? `pi packages: ${added.length} added (${want.length} declared in manifest)`
      : `pi packages: ${want.length} declared (.pi/settings.json created)`);
    if (added.length > 0) log("pi loads project packages after trust — grant it on the first pi session");
  } else {
    log("pi packages unchanged");
  }
}

function mergeProjectMcp(): void {
  const targets = [".pi/mcp.json", ".agents/mcp_config.json"];
  for (const rel of targets) {
    const p = join(PROJECT_ROOT, rel);
    let cfg: Record<string, unknown> = {};
    if (existsSync(p)) {
      try {
        cfg = JSON.parse(readFileSync(p, "utf8"));
      } catch (e) {
        fail(`unparseable JSON — refusing to overwrite: ${p}\n${e instanceof Error ? e.message : e}`);
      }
      if (typeof cfg !== "object" || cfg === null || Array.isArray(cfg)) fail(`expected JSON object: ${p}`);
    }
    const servers = (cfg.mcpServers && typeof cfg.mcpServers === "object" ? cfg.mcpServers : {}) as Record<string, unknown>;
    const before = JSON.stringify(cfg);
    // Template wins for the 9 managed entries (converts literal keys -> env-refs);
    // non-template sibling servers are preserved by construction.
    for (const [k, v] of Object.entries(MCP_TEMPLATE)) servers[k] = v;
    cfg.mcpServers = servers;
    const after = JSON.stringify(cfg);
    if (before === after && existsSync(p)) {
      log(`mcp unchanged: ${rel}`);
      continue;
    }
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, `${JSON.stringify(cfg, null, 2)}\n`);
    log(`mcp written: ${rel}`);
  }
}

// ============================================================ LAYER 3: project AGENTS.md
function extractBlocks(template: string): string[] {
  // Balises are `<!-- app:start -->` (spaces before -->).
  const re = /<!--\s*[a-z0-9]*:start\s*-->[\s\S]*?<!--\s*[a-z0-9]*:end\s*-->/g;
  const blocks = template.match(re) ?? [];
  if (blocks.length !== 9) fail(`AGENTS template must hold exactly 9 balise blocks, found ${blocks.length}`);
  return blocks;
}

function upsertAgents(): void {
  const blocks = extractBlocks(AGENTS_TEMPLATE);
  const p = join(PROJECT_ROOT, "AGENTS.md");
  const exists = existsSync(p);
  let content = exists ? readFileSync(p, "utf8") : "";
  let changed = false;
  for (const block of blocks) {
    const s0 = block.indexOf("<!--");
    const startBalise = block.slice(s0, block.indexOf("-->", s0) + 3);
    const endBalise = block.slice(block.lastIndexOf("<!--"), block.lastIndexOf("-->") + 3);
    const s = content.indexOf(startBalise);
    const e = content.indexOf(endBalise);
    if (s === -1 && e === -1) {
      const sep = content.length === 0 ? "" : content.endsWith("\n") ? "\n" : "\n\n";
      content = content.length === 0 ? `${block}\n` : `${content}${sep}${block}\n`;
      changed = true;
      continue;
    }
    if (s === -1 || e === -1 || e < s) fail(`unbalanced balises (${startBalise}) in ${p} — fix manually, refusing to truncate`);
    const next = content.slice(0, s) + block + content.slice(e + endBalise.length);
    if (next !== content) changed = true;
    content = next;
  }
  if (!exists) {
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, content);
    log("created: AGENTS.md (9 blocks)");
  } else if (changed) {
    writeFileSync(p, content);
    log("updated: AGENTS.md (9 blocks upserted)");
  } else {
    log("AGENTS.md unchanged (9 blocks)");
  }
}

// ============================================================ LAYER 4: project skills
function extractSkills(): void {
  const keys = Object.keys(SKILL_PAYLOAD);
  if (keys.length < 9) fail(`skill payload incomplete (${keys.length} files)`);
  let written = 0;
  let skipped = 0;
  const perApp = new Set<string>();
  for (const [rel, content] of Object.entries(SKILL_PAYLOAD)) {
    const p = join(PROJECT_ROOT, ".agents", "skills", rel);
    perApp.add(rel.split("/")[0]);
    const data = Buffer.from(content, "utf8");
    if (existsSync(p) && readFileSync(p).equals(data)) {
      skipped++;
      continue;
    }
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, data);
    written++;
  }
  if (written > 0) log(`skills deployed: ${written} written, ${skipped} unchanged (${perApp.size} apps) -> .agents/skills/`);
  else log(`skills unchanged (${skipped} files)`);
}

// ---- openspec: CLI ensure + global profile config (documented ~/.config exception) ----
// Structural allowlist: openspec only ever spawned with these joined argv.
// Never `update` (its upgrade offer is interactive).
const OPENSPEC_ALLOWED = new Set(["--version", "config path", "init --tools agents --force"]);
function runOpenspec(args: string[], cwd?: string) {
  const joined = args.join(" ");
  if (!OPENSPEC_ALLOWED.has(joined)) fail(`internal guard: openspec "${joined}" is not on the allowlist`);
  return run("openspec", args, cwd);
}

function ensureOpenspec(): void {
  const pkg = "@fission-ai/openspec";
  const current = runOpenspec(["--version"]);
  const installed = current.code === 0 ? (current.stdout.match(/(\d+\.\d+\.\d+)/)?.[1] ?? null) : null;
  if (installed === null) {
    log("openspec missing — installing globally via npm...");
    const r = run("npm", ["install", "-g", pkg]);
    if (r.code !== 0) fail(`npm install -g ${pkg} failed (exit ${r.code}):\n${r.stderr}`);
    const after = runOpenspec(["--version"]);
    if (after.code !== 0) fail("openspec still not on PATH after install");
    log(`installed openspec ${after.stdout.trim()}`);
    return;
  }
  const v = run("npm", ["view", pkg, "version"]);
  if (v.code !== 0 || !v.stdout.trim()) {
    warn(`npm registry unreachable — skipping openspec update check (local ${installed})`);
    return;
  }
  const latest = v.stdout.trim();
  if (latest === installed) {
    log(`openspec up to date (${installed})`);
    return;
  }
  log(`openspec ${installed} < latest ${latest} — installing update...`);
  const r = run("npm", ["install", "-g", pkg]);
  if (r.code !== 0) fail(`npm install -g ${pkg} failed (exit ${r.code}):\n${r.stderr}`);
  const after = runOpenspec(["--version"]);
  if (after.code !== 0) fail("openspec not identifiable after update");
  log(`openspec update complete (${after.stdout.trim()})`);
}

function ensureOpenspecConfig(): void {
  const p = runOpenspec(["config", "path"]);
  if (p.code !== 0 || !p.stdout.trim()) fail(`cannot resolve openspec config path:\n${p.stderr || p.stdout}`);
  const configPath = (p.stdout.trim().split("\n").pop() ?? "").trim();
  if (!configPath) fail("empty openspec config path");
  let cfg: Record<string, unknown> = {};
  if (existsSync(configPath)) {
    try {
      cfg = JSON.parse(readFileSync(configPath, "utf8"));
    } catch (e) {
      fail(`unparseable JSON — refusing to overwrite: ${configPath}\n${e instanceof Error ? e.message : e}`);
    }
    if (typeof cfg !== "object" || cfg === null || Array.isArray(cfg)) fail(`expected JSON object: ${configPath}`);
  }
  const before = JSON.stringify(cfg);
  // Canonical 3 keys in; every other top-level key preserved verbatim. Zero secrets.
  cfg.profile = "custom";
  cfg.delivery = "skills";
  cfg.workflows = ["propose", "explore", "new", "continue", "apply", "update", "ff", "sync", "archive", "bulk-archive", "verify", "onboard"];
  if (before === JSON.stringify(cfg)) {
    log(`openspec config unchanged: ${configPath}`);
    return;
  }
  mkdirSync(dirname(configPath), { recursive: true });
  writeFileSync(configPath, `${JSON.stringify(cfg, null, 2)}\n`);
  log(`openspec config written: ${configPath} (profile=custom, delivery=skills, 12 workflows)`);
}

// ---- foundation (STEP 0 — runs FIRST): rule-book base + upgrade cleanup ----
function writeBase(): void {
  const p = join(PROJECT_ROOT, "AGENTS.md");
  if (existsSync(p) && readFileSync(p, "utf8") === BASE_PAYLOAD) {
    log("AGENTS.md base unchanged");
    return;
  }
  writeFileSync(p, BASE_PAYLOAD);
  log(existsSync(p) ? "AGENTS.md base written (rule book)" : "AGENTS.md base created");
}

// Enumerated upgrade cleanup ONLY — every other foreign skill stays untouched.
function purgeFoundationLeftovers(): void {
  const manifest = join(PROJECT_ROOT, ".agents", "skills", ".agentic-manifest.json");
  if (existsSync(manifest)) {
    rmSync(manifest);
    log("removed stale .agentic-manifest.json");
  }
  const orphan = join(PROJECT_ROOT, ".agents", "skills", "qmd-research");
  if (existsSync(orphan)) {
    rmSync(orphan, { recursive: true, force: true });
    log("removed dropped skill: .agents/skills/qmd-research/");
  }
}

// Developer tool (per check-deps delivery contract): ./scripts/check-deps.ts
function deployScript(): void {
  const dir = join(PROJECT_ROOT, "scripts");
  const p = join(dir, "check-deps.ts");
  if (existsSync(p) && readFileSync(p, "utf8") === SCRIPT_PAYLOAD) {
    log("scripts/check-deps.ts unchanged");
    return;
  }
  mkdirSync(dir, { recursive: true });
  writeFileSync(p, SCRIPT_PAYLOAD);
  log("scripts/check-deps.ts deployed");
}

function ensureReportsDir(): void {
  if (!existsSync(join(PROJECT_ROOT, "openspec"))) return;
  const dir = join(PROJECT_ROOT, "openspec", "reports");
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
    log("openspec/reports/ created");
  }
}

// ---- qmd default knowledge collections (seed after init; skip-by-name) ----
function splitQmdCommand(cmd: string): string[] {
  return (cmd.match(/"[^"]*"|\S+/g) ?? []).map((t) => (t.startsWith('"') && t.endsWith('"') ? t.slice(1, -1) : t));
}

function seedQmdCollections(): void {
  if (!existsSync(join(PROJECT_ROOT, ".qmd"))) return;
  const catalog = JSON.parse(DEFAULT_DB_PAYLOAD) as Record<string, string>;
  const list = run("qmd", ["collection", "list"]);
  const listed = list.code === 0 ? list.stdout : "";
  let created = 0;
  let skipped = 0;
  for (const [name, cmd] of Object.entries(catalog)) {
    if (new RegExp(`(^|\\s)${name}($|\\s)`).test(listed)) {
      skipped++;
      continue;
    }
    const argv = splitQmdCommand(cmd);
    const addIdx = argv.findIndex((a) => a === "add");
    const rootPath = addIdx >= 0 ? argv[addIdx + 1] : undefined;
    if (rootPath && !existsSync(join(PROJECT_ROOT, rootPath))) {
      log(`qmd collection ${name}: skipped (root path missing: ${rootPath})`);
      skipped++;
      continue;
    }
    const r = run(argv[0], argv.slice(1));
    if (r.code !== 0) warn(`qmd collection ${name} failed (exit ${r.code}): ${(r.stderr || r.stdout).trim()}`);
    else created++;
  }
  log(`qmd collections: ${created} created, ${skipped} skipped (of ${Object.keys(catalog).length})`);
  const up = run("qmd", ["update"]);
  if (up.code !== 0) warn(`qmd update failed (exit ${up.code}): ${(up.stderr || up.stdout).trim()}`);
  else log("qmd update: index refreshed");
}

// ============================================================ LAYER 5: repo inits
function runInits(): void {
  const jobs: Array<{ marker: string; label: string; cmd: string; args: string[]; always?: boolean }> = [
    { marker: "graft", label: "graft build", cmd: "graft", args: ["build"] },
    { marker: ".qmd", label: "qmd init", cmd: "qmd", args: ["init", "."] },
    { marker: ".codegraph", label: "codegraph init", cmd: "codegraph", args: ["init"] },
    // openspec: ALWAYS runs — user's canonical `openspec init --tools agents --force` (no marker gate).
    { marker: "", label: "openspec init", cmd: "openspec", args: ["init", "--tools", "agents", "--force"], always: true },
  ];
  for (const j of jobs) {
    if (!j.always && existsSync(join(PROJECT_ROOT, j.marker))) {
      log(`${j.label}: skipped (${j.marker} exists)`);
      continue;
    }
    log(`${j.label}: running...`);
    const r = run(j.cmd, j.args, PROJECT_ROOT);
    if (r.code !== 0) fail(`${j.label} failed (exit ${r.code}):\n${(r.stdout + r.stderr).trim()}`);
    log(`${j.label}: done`);
  }
}

// ============================================================ main
async function main(): Promise<void> {
  // STEP 0: foundation FIRST — rule-book base must exist before the balise
  // upsert (later layer) appends our 9 blocks onto it; upgrade cleanup runs here.
  writeBase();
  purgeFoundationLeftovers();
  // Prerequisites: provision Node 22 + uv first (npm/npx + uv gates then pass).
  await ensureNode();
  await ensureUv();
  // Layer 1: machine (the 9 app CLIs + LSP bins never touch dotfiles;
  // openspec's global config is the ONE documented ~/.config exception)
  ensureQmd();
  await ensureSem();
  ensureGraft();
  ensureCodegraph();
  await ensureHeadroom();
  await ensureBenzi();
  gateJcodemunch();
  gateContext7();
  gateJev();
  ensureOpenspec();
  ensureOpenspecConfig();
  await ensureLspBins();
  // Layers 2-5: project tree only
  mergeProjectMcp();
  mergePiSettings();
  writeLspConfig();
  upsertAgents();
  extractSkills();
  deployScript();
  runInits();
  seedQmdCollections();
  ensureReportsDir();
  log("done — project initialized");
}

main();
